"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import axiosInstance from "@/utils/axiosInstance";
import { Product, ProductStatus, Category } from "@/types/product";
import { useCategories } from "@/hooks/useCategories";
import ProductFormSkeleton from "./productFormSkeleton";
import FormDetails from "@/components/product/draft/FormDetails";
import ProductImages from "@/components/product/draft/ProductImages";
import Button from "@/components/product/draft/Button";
import { toast, ToastContainer } from "react-toastify";

const ProductDraftForm = () => {
  const params = useParams();
  const productId = params?.productId as string;
  const router = useRouter();
  const { data: categoryData, isLoading } = useCategories(1, 100, "");
  const [productData, setProductData] = useState<Product | null>(null);
  const [isSubmitting, setSubmitting] = useState(false);
  const [localProductPictures, setLocalProductPictures] = useState<(string | null)[]>([null, null, null]);
  const [showCancelModal, setShowCancelModal] = useState(false);

  const fetchProducts = async () => {
    try {
      const response = await axiosInstance.get<Product>(`/products/${productId}`);
      const product = response.data;
      if (!product || Object.values(product).every((value) => value === null)) {
        router.push("/404");
        return;
      }
      setProductData(product);
      if (product.status !== ProductStatus.DRAFT) {
        router.push("/403");
        return;
      }
    } catch (error) {
      router.push("/404");
    }
  };

  useEffect(() => {
    if (productId && !productData) {
      fetchProducts();
    }
  }, [productId]);

  const handleCancel = () => setShowCancelModal(true);

  const handleSaveDraft = async () => {
    try {
      await axiosInstance.patch(`/products/${productId}/draft`, formik.values);
      router.push("/dashboard/admin/products");
      localStorage.setItem('toastMessage', 'Draft saved successfully!');
    } catch (error) {
      localStorage.setItem('toastMessage', 'Failed to save draft');
    }
  };

  const handleDeleteProduct = async () => {
    try {
      await axiosInstance.delete(`/products/${productId}/delete`);
      router.push("/dashboard/admin/products");
      localStorage.setItem('toastMessage', 'Draft deleted successfully!');
    } catch (error) {
      localStorage.setItem('toastMessage', 'Failed to delete the draft');
    }
  };

  return (
    <div className="p-8 bg-white shadow-lg rounded-xl max-w-3xl mx-auto">
      <ToastContainer />
      {isLoading || !productData ? (
        <ProductFormSkeleton />
      ) : (
        <>
          <h2 className="text-3xl font-bold mb-6 text-center text-gray-800">📝 Create Product Form</h2>
          <FormDetails productData={productData} />
          <ProductImages 
            localProductPictures={localProductPictures} 
            setLocalProductPictures={setLocalProductPictures}
            productId={productId}
            setSubmitting={setSubmitting}
            formik={formik} 
          />
          <div className="flex flex-col md:flex-row space-y-3 md:space-y-0 md:space-x-4">
            <Button type="submit" label={isSubmitting ? "Creating..." : "Create Product"} disabled={isSubmitting} />
            <Button type="button" label="Cancel" onClick={handleCancel} />
          </div>
        </>
      )}
    </div>
  );
};

export default ProductDraftForm;