import { FC } from "react";

interface ButtonProps {
  type: "button" | "submit";
  label: string;
  onClick?: () => void;
  disabled?: boolean;
}

const Button: FC<ButtonProps> = ({ type, label, onClick, disabled }) => (
  <button
    type={type}
    onClick={onClick}
    className={`bg-blue-600 hover:bg-blue-700 transition text-lg text-white px-6 py-3 rounded-lg w-full md:w-auto font-medium shadow-md ${disabled ? "opacity-50 cursor-not-allowed" : ""}`}
    disabled={disabled}
  >
    {label}
  </button>
);

export default Button;